@startuml

class EBike {
  + modelName : string
  + manufacturer : string
}

class Frame {
  + material : string
}

class DriveSystem {
  + maxTorque : double
}

class Motor {
  + powerOutput : double
}

class Controller {
  + state : ControllerState
}

class Battery {
  + storedEnergyWh : double
  + isRemovable : boolean
}

class Wheel {
  + diameter : double
}

class BasicController {}

class AdvancedController {
  + nextMaintenanceDate : date
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "1" *-- "0..1" Battery
EBike "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
Controller --|> BasicController
Controller --|> AdvancedController
Controller "1" --> "0..1" Battery : controls
Controller "1" --> "1" DriveSystem : commands

@enduml

